class Solution {
    long long best(vector<vector<int>>& f, bool T) {
        int n = f.size();
        const long long NEG = LLONG_MIN / 4;
        vector<long long> dp(n, NEG), nd(n);
        dp[n - 1] = T ? f[n - 1][0] : f[0][n - 1];
        for (int r = 1; r < n; r++) {
            for (int c = r; c < n; c++) {
                long long b = NEG;
                if (c - 1 >= r - 1) b = max(b, dp[c - 1]);
                b = max(b, dp[c]);
                if (c + 1 <= n - 1) b = max(b, dp[c + 1]);
                long long v = 0;
                if (c > r) v = T ? f[c][r] : f[r][c];
                nd[c] = (b == NEG) ? NEG : b + v;
            }
            swap(dp, nd);
        }
        return dp[n - 1];
    }
public:
    int maxCollectedFruits(vector<vector<int>>& fruits) {
        int n = fruits.size();
        long long ans = 0;
        for (int i = 0; i < n; i++) ans += fruits[i][i];
        ans += best(fruits, false);
        ans += best(fruits, true);
        return (int)ans;
    }
};
